export const events = {
	jobUpdates: makeEvent<JobUpdates>("job-updates"),
	scannedFiles: makeEvent<ScannedFiles>("scanned-files"),
	volumesChanged: makeEvent<VolumesChanged>("volumes-changed"),
};

